464	    /**
465	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
466	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
467	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
468	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
469	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
470	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
471	     *
472	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
473	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
474	     */
475	    private Integer findPossibleDuplicateOf(Owner owner) {
476	        String postcode = owner.getPostcode();
477	        if (postcode == null) {
478	            return null;
479	        }
480	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
481	        String telephone = owner.getTelephone();
482	        return this.clinicService.findAllOwners().stream()
483	            .filter(this::isNotDeleted)
484	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
485	            .filter(existing -> postcode.equals(existing.getPostcode()))
486	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
487	            .map(Owner::getId)
488	            .filter(java.util.Objects::nonNull)
489	            .min(java.util.Comparator.naturalOrder())
490	            .orElse(null);
491	    }
