493	    /**
494	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
495	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
496	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
497	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
498	     * {@code "+61412345678"}. The E.164 value is stored and returned.
499	     * <p>
500	     * The national-number length (the digits after the country code) is additionally validated for
501	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
502	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
503	     *
504	     * @param telephone the raw telephone as submitted
505	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
506	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
507	     *         or its national-number length is wrong for its country code
508	     */
509	    private String normalizeTelephone(String telephone) {
510	        String raw = telephone == null ? "" : telephone.trim();
511	        boolean hasCountryCode = raw.startsWith("+");
512	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
513	        if (hasCountryCode) {
514	            cleaned = cleaned.substring(1);
515	        }
516	        String digits;
517	        if (hasCountryCode) {
518	            digits = cleaned;
519	        } else {
520	            if (cleaned.startsWith("0")) {
521	                cleaned = cleaned.substring(1);
522	            }
523	            digits = "61" + cleaned;
524	        }
525	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
526	            throw new InvalidTelephoneException(telephone);
527	        }
528	        return "+" + digits;
529	    }
530	
531	    /**
532	     * Checks the national-number length of an E.164 digit string against its country code for the
533	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
534	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
535	     *
536	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
537	     * @return {@code true} if the national-number length is acceptable for the country code
538	     */
539	    private boolean hasValidNationalLength(String digits) {
540	        if (digits.startsWith("61")) {
541	            return digits.length() - 2 == 9;
542	        }
543	        if (digits.startsWith("1")) {
544	            return digits.length() - 1 == 10;
545	        }
546	        return true;
547	    }
