549	    /**
550	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
551	     * multi-character top-level label. Deliberately lenient about the exact character set while still
552	     * rejecting values that are clearly not addresses (e.g. missing '@').
553	     */
554	    private static final java.util.regex.Pattern EMAIL_PATTERN =
555	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
556	
557	    /**
558	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
559	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
560	     * lower-cased email domain.
561	     */
562	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
563	        "mailinator.com", "tempmail.com", "guerrillamail.com");
564	
565	    /**
566	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
567	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
568	     * lower-cased before being stored and returned.
569	     *
570	     * @param email the raw email as submitted, may be {@code null}
571	     * @return the lower-cased email, or {@code null} when none was supplied
572	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
573	     */
574	    private String normalizeEmail(String email) {
575	        if (email == null || email.isBlank()) {
576	            return null;
577	        }
578	        String trimmed = email.trim();
579	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
580	            throw new InvalidEmailException(email);
581	        }
582	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
583	        String domain = normalized.substring(normalized.indexOf('@') + 1);
584	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
585	            throw new DisposableEmailException(email);
586	        }
587	        return normalized;
588	    }
