590	    /**
591	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
592	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
593	     * {@link Localities#region}) accepts any 4-digit postcode.
594	     */
595	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
596	        "NSW", new int[] {2000, 2099},
597	        "VIC", new int[] {3000, 3099},
598	        "QLD", new int[] {4000, 4099});
599	
600	    /**
601	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
602	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
603	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
604	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
605	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
606	     *
607	     * @param city the owner's city, used to derive the region whose range constrains the postcode
608	     * @param postcode the raw postcode as submitted, may be {@code null}
609	     * @return the postcode when supplied, or {@code null} when none was supplied
610	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
611	     *         out of range for the city's region
612	     */
613	    private String validatePostcode(String city, String postcode) {
614	        if (postcode == null || postcode.isBlank()) {
615	            return null;
616	        }
617	        if (!postcode.matches("[0-9]{4}")) {
618	            throw new InvalidPostcodeException(postcode);
619	        }
620	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
621	        if (range != null) {
622	            int value = Integer.parseInt(postcode);
623	            if (value < range[0] || value > range[1]) {
624	                throw new InvalidPostcodeException(postcode);
625	            }
626	        }
627	        return postcode;
628	    }
629	
630	    /**
631	     * Common street-type abbreviations expanded to their full word during address normalization.
632	     */
633	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
634	        "ST", "STREET",
635	        "RD", "ROAD",
636	        "AVE", "AVENUE");
637	
638	    /**
639	     * Applies the owner's address on create from the structured fields when present, falling back to the
640	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
641	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
642	     * {@code address}; when neither is present the create is rejected.
643	     * <p>
644	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
645	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
646	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
647	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
648	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
649	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
650	     *
651	     * @param owner the owner being created
652	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
653	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
654	     */
655	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
656	        String rawLine1 = ownerFieldsDto.getAddressLine1();
657	        String rawLine2 = ownerFieldsDto.getAddressLine2();
658	        String rawFlat = ownerFieldsDto.getAddress();
659	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
660	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
661	        if (!hasLine1 && !hasFlat) {
662	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
663	        }
664	        if (hasLine1) {
665	            String line1 = normalizeAddress(rawLine1);
666	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
667	            owner.setAddressLine1(line1);
668	            owner.setAddressLine2(line2);
669	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
670	        } else {
671	            owner.setAddressLine1(null);
672	            owner.setAddressLine2(null);
673	            owner.setAddress(normalizeAddress(rawFlat));
674	        }
675	    }
676	
677	    /**
678	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
679	     * whitespace collapse to a single space, the value is upper-cased and common street-type
680	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
681	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
682	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
683	     * for every address comparison (household duplicate detection and the shared household id).
684	     *
685	     * @param address the raw address as submitted
686	     * @return the normalized address
687	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
688	     */
689	    private String normalizeAddress(String address) {
690	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
691	        if (collapsed.isEmpty()) {
692	            throw new InvalidAddressException(address);
693	        }
694	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
695	        StringBuilder normalized = new StringBuilder(collapsed.length());
696	        for (int i = 0; i < tokens.length; i++) {
697	            if (i > 0) {
698	                normalized.append(' ');
699	            }
700	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
701	        }
702	        return normalized.toString();
703	    }
