705	    /**
706	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
707	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
708	     * owners are duplicates when they share the same normalized telephone and the same normalized email
709	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
710	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
711	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
712	     * still match.
713	     * <p>
714	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
715	     * grouping, so two members of the same household with different telephones have different
716	     * identities and are both allowed. Only owners with the same telephone and email collide.
717	     *
718	     * @param owner the owner being created, with its telephone and email already normalized
719	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
720	     */
721	    private void rejectDuplicateIdentity(Owner owner) {
722	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
723	        boolean duplicate = this.clinicService.findAllOwners().stream()
724	            .filter(this::isNotDeleted)
725	            .anyMatch(existing -> identity.equals(
726	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
727	        if (duplicate) {
728	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
729	            throw new DuplicateIdentityException(
730	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
731	        }
732	    }
733	
734	    /**
735	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
736	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
737	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
738	     */
739	    /**
740	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
741	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
742	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
743	     */
744	    private boolean isNotDeleted(Owner owner) {
745	        return !Boolean.TRUE.equals(owner.getDeleted());
746	    }
747	
748	    private String personalIdentity(String telephone, String email) {
749	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
750	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
751	    }
752	
753	    /**
754	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
755	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
756	     * when its national-number length does not match its country code.
757	     */
758	    private String toE164OrNull(String telephone) {
759	        try {
760	            return normalizeTelephone(telephone);
761	        } catch (InvalidTelephoneException e) {
762	            return null;
763	        }
764	    }
