		b.put("lastName", lastName);
		b.put("postcode", "2000");
		b.put("sharesHousehold", true); // bypass the duplicate block
		int idb = createOwnerOk(b);
		assertEquals(fetchOwner(ida).get("householdId").asText(),
				fetchOwner(idb).get("householdId").asText());
	}
}
